def standard():
    x = Symbol('x')
    h = expand((-6)*x**0+(2)*x**1+(6)*x**2+(-2)*x**3)
    pts = [Integer(-1)] + sorted(set(r for r in solve(h, x) if r.is_real and -1 < r < 3)) + [Integer(3)]
    tot = 0
    for p_, q_ in zip(pts, pts[1:]):
        tot += Abs(integrate(h, (x, p_, q_)))
    tot = tot*Rational(2, 1)
    return int(tot)

def unique():
    return [standard()]
